  1	import React from 'react';
  2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
  3	import { ZimmLogo } from 'app/components/ui-kits/atoms/zimmLogo';
  4	import { ZimmSubscribeSection } from 'app/components/ui-kits/organisms/zimmSubscribeSection';
  5	import { noop } from '@salesforce/retail-react-app/app/utils/utils';
  6	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
  7	import { useHistory } from 'react-router-dom';
  8	import { HOME_HREF } from '@salesforce/retail-react-app/app/constants';
  9	import type { FooterConfigEntry } from 'app/types/contentful';
 10	import { FOOTER_FIXTURE } from './contentfulFixture';
 11	import { FooterNavColumn } from './footerNavColumn';
 12	import { BottomBar } from './bottomBar';
 13	
 14	const ZIMM_FOOTER_RECIPE = 'ZimmFooter';
 15	
 16	// ---------------------------------------------------------------------------
 17	// Types
 18	// ---------------------------------------------------------------------------
 19	type FooterProps = {
 20	  /** Contentful FooterConfigEntry. Pass FOOTER_FIXTURE from contentfulFixture.ts in stories/tests. */
 21	  data: FooterConfigEntry;
 22	  copyrightYear?: number;
 23	  /** Forces SubscribeSection into its post-submit state. For Storybook/tests only. */
 24	  initialSubscribed?: boolean;
 25	  /**
 26	   * Opt in to the HPC-035 first/last-name capture modal. Defaults to false: SFCC-55 ships the
 27	   * Stay in Touch section as an input plus submit button only, and the modal has no design yet.
 28	   */
 29	  enableNameCapture?: boolean;
 30	  /** Click handler for the wordmark. Mirrors the header's onLogoClick prop, defaulting to
 31	   *  noop so the presentational Footer never navigates on its own. */
 32	  onLogoClick?: () => void;
 33	  /** href for the Privacy Policy link inside the subscribe modal (HPC-037). Locale-aware at runtime. */
 34	  privacyPolicyHref?: string;
 35	};
 36	
 37	// ---------------------------------------------------------------------------
 38	// Footer
 39	// ---------------------------------------------------------------------------
 40	
 41	/**
 42	 * Zimmermann global footer — presentational. Receives its content as props and fetches
 43	 * nothing, matching every other Contentful-backed component in the repo (`DuplexSection`,
 44	 * `HeroBanner`, `ProductHero`, `VideoEmbed`).
 45	 *
 46	 * Composed from independently-exported organisms/molecules (ui-kits/organisms/
 47	 * zimmSubscribeSection, ui-kits/molecules/zimmContactIconRow via FooterNavColumn) rather than
 48	 * defining them inline — see .claude/rules/overrideStyling.md for the reasoning. This file owns
 49	 * only the footer's own shell layout: content row, nav-column wrapper, logo band, bottom bar.
 50	 *
 51	 * `data` is required by design: static content belongs in the story or in the container below,
 52	 * never baked into the component that renders production UI. Omneo email submit and Cookie
 53	 * Settings are separate stories (HPC-035, HPC-038).
 54	 */
 55	export const Footer = ({
 56	  data,
 57	  copyrightYear = new Date().getFullYear(),
 58	  initialSubscribed = false,
 59	  privacyPolicyHref = '#',
 60	  onLogoClick = noop,
 61	  enableNameCapture = false,
 62	}: FooterProps) => {
 63	  const {
 64	    subscribeHeading,
 65	    subscribeBody,
 66	    navGroups,
 67	    legalLinks = [],
 68	    copyrightOwner,
 69	    phoneHref,
 70	    whatsAppHref,
 71	    emailHref,
 72	  } = data.fields;
 73	
 74	  const legalItems = legalLinks.map((e) => ({ label: e.fields.label, href: e.fields.href }));
 75	  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});
 76	
 77	  return (
 78	    <chakra.footer role="contentinfo" __css={styles.container}>
 79	      <chakra.div __css={styles.main}>
 80	        <chakra.div __css={styles.contentRow}>
 81	          <chakra.div __css={styles.subscribe}>
 82	            <ZimmSubscribeSection
 83	              heading={subscribeHeading ?? ''}
 84	              body={subscribeBody ?? ''}
 85	              initialSubscribed={initialSubscribed}
 86	              privacyPolicyHref={privacyPolicyHref}
 87	              enableNameCapture={enableNameCapture}
 88	            />
 89	          </chakra.div>
 90	
 91	          <chakra.div __css={styles.links}>
 92	            <chakra.div __css={styles.linksInner}>
 93	              {navGroups.map((group) => (
 94	                <FooterNavColumn
 95	                  key={group.sys.id}
 96	                  group={group}
 97	                  phoneHref={phoneHref}
 98	                  whatsAppHref={whatsAppHref}
 99	                  emailHref={emailHref}
100	                />
101	              ))}
102	            </chakra.div>
103	          </chakra.div>
104	        </chakra.div>
105	
106	        <chakra.div __css={styles.logo}>
107	          {/* Button + programmatic nav, matching the header's wordmark rather than an <a href>.
108	              The handler comes from FooterContainer — see the note there on why it uses
109	              buildUrl + history.push rather than useNavigation. styles.logoButton is a chrome
110	              reset only, so the logo keeps its own geometry. */}
111	          <chakra.button type="button" aria-label="Zimmermann home" onClick={onLogoClick} __css={styles.logoButton}>
112	            <ZimmLogo variant="inverse" />
113	          </chakra.button>
114	        </chakra.div>
115	      </chakra.div>
116	
117	      <BottomBar copyrightYear={copyrightYear} copyrightOwner={copyrightOwner ?? ''} legalLinks={legalItems} />
118	    </chakra.footer>
119	  );
120	};
121	
122	// ---------------------------------------------------------------------------
123	// Container — the default export
124	// ---------------------------------------------------------------------------
125	
126	/**
127	 * The component SFCC actually renders. Base `_app/index.jsx` resolves
128	 * `@salesforce/retail-react-app/app/components/footer` through the overrides system and renders
129	 * `<Footer />` with **no props**, so there is no upstream container to own the data. This
130	 * wrapper is that seam, and the only place static content lives.
131	 *
132	 * HPC-034: replace FOOTER_FIXTURE with the Contentful CDA fetch **here** — the presentational
133	 * Footer above does not change. Note that puts a fetch inside `components/`, which
134	 * components.md reserves for containers; if that matters, HPC-034 should override `_app`
135	 * instead (Tier 2 shared shell — coordinate first).
136	 */
137	const FooterContainer = (props: Omit<FooterProps, 'data'>) => {
138	  // buildUrl + history.push, not useNavigation. useNavigation special-cases the home path
139	  // (`path === '/' ? '/' : updatedHref`), so navigate('/') pushes a bare '/' and skips the
140	  // site/locale prefix — on a prefixed storefront that drops the shopper onto the default
141	  // site. This is the exact pair base _app's onLogoClick uses, so both wordmarks resolve home
142	  // the same way on every storefront.
143	  const { buildUrl } = useMultiSite();
144	  const history = useHistory();
145	  return <Footer data={FOOTER_FIXTURE} onLogoClick={() => history.push(buildUrl(HOME_HREF))} {...props} />;
146	};
147	
148	export default FooterContainer;

