     1	import React from 'react';
     2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
     3	import { ZimmIcon } from 'app/components/ui-kits/atoms/zimmIcon';
     4	import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem';
     5	import { useUiCopy } from 'app/hooks/useUiCopy';
     6	
     7	const ZIMM_FOOTER_BOTTOM_BAR_RECIPE = 'ZimmFooterBottomBar';
     8	
     9	// Locale control label. Hardcoded, and deliberately NOT fixture data — region and currency come
    10	// from site config (config/default.js: defaultSite 'ZimmermannAU'), not Contentful, so
    11	// FooterConfigEntry has no field for them. Set to match the site the app actually serves at
    12	// '/'; it previously read "United States (USD) / ENG" on an AU storefront. The real fix reads
    13	// site.l10n.defaultLocale and the site's currency via useMultiSite when the locale selector
    14	// lands, at which point this constant goes away rather than getting a different literal.
    15	const LOCALE_LABEL_PLACEHOLDER = 'Australia (AUD) / ENG';
    16	
    17	type BottomBarProps = {
    18	  copyrightYear: number;
    19	  copyrightOwner: string;
    20	  legalLinks: ReadonlyArray<{ label: string; href: string }>;
    21	};
    22	
    23	/**
    24	 * Footer bottom bar — locale switcher (placeholder, not yet wired), copyright, and legal links.
    25	 * Single-parent internal component (only Footer renders it), so per components.md it doesn't
    26	 * need its own story — covered by footer/index.stories.tsx's assembly-level coverage.
    27	 *
    28	 * @param props see BottomBarProps
    29	 */
    30	export const BottomBar = ({ copyrightYear, copyrightOwner, legalLinks }: BottomBarProps) => {
    31	  const styles = useMultiStyleConfig(ZIMM_FOOTER_BOTTOM_BAR_RECIPE, {});
    32	  // Sourced directly, not threaded through as a prop — uiCopy is app-wide static microcopy,
    33	  // safe to read from any component the same way useIntl() already is. Falls back to the
    34	  // English literal with no UiCopyProvider mounted (Storybook, this component's own tests).
    35	  const { t } = useUiCopy();
    36	  const copyrightLabel = t('footer.copyright.label', 'Copyright');
    37	  return (
    38	    <chakra.div __css={styles.bar}>
    39	      <chakra.div __css={styles.inner}>
    40	        {/* PLACEHOLDER: wire to locale selector once available. Rendered as a non-interactive
    41	            div, not a button, so nothing promises an action that cannot be performed (WCAG
    42	            3.2.4 / 4.1.2) — same treatment ZimmContactIconRow gives an unusable channel.
    43	            Label and destination are hardcoded until sourced from active locale/site config.
    44	            Swap back to a real button with an onClick when the selector lands. */}
    45	        <chakra.div __css={styles.localeButton}>
    46	          {/* localeText = Figma "footer-item": py-8px on text only, icon sits outside.
    47	              Typography and colour are inherited from the parent localeButton theme. */}
    48	          <chakra.span __css={styles.localeText}>{LOCALE_LABEL_PLACEHOLDER}</chakra.span>
    49	          <ZimmIcon type="chevron-right" size="sm" aria-hidden={true} />
    50	        </chakra.div>
    51	
    52	        <chakra.div __css={styles.right}>
    53	          {/* Copyright is a direct flex child of `right` to match Figma's flat Legal row.
    54	              py-8px matches the legal link py used in ZimmNavItem style below. */}
    55	          <chakra.span __css={styles.copyright}>
    56	            {copyrightLabel} &copy; {copyrightYear} {copyrightOwner}
    57	          </chakra.span>
    58	          <chakra.div __css={styles.legalGrid}>
    59	            {legalLinks.map((link) => (
    60	              <ZimmNavItem
    61	                key={link.label}
    62	                href={link.href}
    63	                label={link.label}
    64	                inverse
    65	                // Figma Small/Default: py-[8px] — override base h-[24px] with height:auto + vertical padding
    66	                // width is applied via legalGrid's '& > a' child selector in bottomBar.css.ts
    67	                sx={styles.legalLink}
    68	              />
    69	            ))}
    70	          </chakra.div>
    71	        </chakra.div>
    72	      </chakra.div>
    73	    </chakra.div>
    74	  );
    75	};
########## overrides/app/components/footer/footerNavColumn/index.tsx
     1	import React from 'react';
     2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
     3	import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem';
     4	import { ZimmContactIconRow } from 'app/components/ui-kits/molecules/zimmContactIconRow';
     5	import type { FooterNavGroupEntry } from 'app/types/contentful';
     6	
     7	const ZIMM_FOOTER_NAV_COLUMN_RECIPE = 'ZimmFooterNavColumn';
     8	
     9	// Non-breaking space. Marks a label whose line break is intentional — see the nav item below.
    10	const NBSP = ' ';
    11	
    12	/**
    13	 * True when a label carries a deliberate NBSP wrap point (e.g. "Acknowledgement of Country")
    14	 * — see the width:min-content comment below for why this must stay gated rather than applied to
    15	 * every label. Extracted as a named export so the gate itself is unit-testable without asserting
    16	 * on Chakra's `sx`-generated CSS output.
    17	 */
    18	export const hasIntentionalLineBreak = (label: string): boolean => label.includes(NBSP);
    19	
    20	type FooterNavColumnProps = {
    21	  group: FooterNavGroupEntry;
    22	  phoneHref?: string;
    23	  whatsAppHref?: string;
    24	  emailHref?: string;
    25	};
    26	
    27	/**
    28	 * One footer nav column: heading, link list, and (for the Contact group) the contact-channel
    29	 * icon row. Extracted from Footer's inline JSX — this is where the Figma pixel-precision
    30	 * workarounds below actually live now, rather than being buried in the footer assembly.
    31	 *
    32	 * @param props see FooterNavColumnProps
    33	 */
    34	export const FooterNavColumn = ({ group, phoneHref, whatsAppHref, emailHref }: FooterNavColumnProps) => {
    35	  const styles = useMultiStyleConfig(ZIMM_FOOTER_NAV_COLUMN_RECIPE, {});
    36	
    37	  return (
    38	    <chakra.div __css={styles.col}>
    39	      {/* Figma section column: flex-col gap-16px — the column gap replaces marginBottom on the
    40	          heading. Contact heading has 4px left offset. */}
    41	      <chakra.p
    42	        __css={{
    43	          ...styles.heading,
    44	          ...(group.fields.showContactChannels ? { paddingLeft: 'var(--zimm-scale-2xs)' } : {}),
    45	        }}
    46	      >
    47	        {group.fields.heading}
    48	      </chakra.p>
    49	      {/* Figma Links div (2228:19423): flex-col, items-start, width 100%, gap 0.
    50	          DELIBERATE DEVIATION: Figma puts the Contact items at x=0 while indenting only its
    51	          heading 4px (wrapper 40000407:22289) — About and Help headings sit flush at 0, so that
    52	          asymmetry reads as a stray wrapper rather than intent. We indent the Contact items to
    53	          match their heading so the column aligns as a unit. The icon row below needs no
    54	          indent: its 24px box centres a 16px glyph, so the glyph edge already lands at 4px.
    55	          Pending Kiera. */}
    56	      <chakra.ul __css={styles.list}>
    57	        {group.fields.links.map((link) => (
    58	          <chakra.li
    59	            key={link.sys.id}
    60	            __css={{
    61	              ...styles.listItem,
    62	              ...(group.fields.showContactChannels ? { paddingLeft: 'var(--zimm-scale-2xs)' } : {}),
    63	            }}
    64	          >
    65	            {/* Each item h-[24px] items-center, no gap. ZimmNavItem's baseStyle supplies
    66	                minHeight 24px, whiteSpace normal (so the label below can wrap) and uppercase.
    67	
    68	                width:min-content only for labels that carry a non-breaking space. A wrapped
    69	                element takes the AVAILABLE width, not its longest line, so without this the
    70	                Acknowledgement item filled the column's 160px cap while its longest line is
    71	                115px — 45px of dead space that pushed the Contact column right, against Figma
    72	                where every column hugs its content. min-content resolves to the widest
    73	                unbreakable run, which the NBSP makes exactly "ACKNOWLEDGEMENT" (115px). It must
    74	                stay gated: applied to a single-line label it collapses to the longest word and
    75	                wraps it ("Book an Appointment" 131px -> 76px, two lines). */}
    76	            <ZimmNavItem
    77	              href={link.fields.href}
    78	              label={link.fields.label}
    79	              inverse
    80	              sx={hasIntentionalLineBreak(link.fields.label) ? { width: 'min-content' } : undefined}
    81	            />
    82	          </chakra.li>
    83	        ))}
    84	        {/* Contact channels are the LAST CHILD OF THE LIST, not a sibling of it — Figma's
    85	            Icon-list (40002081:14616) sits inside Links at y=72, directly after "CONNECT WITH
    86	            US" ends at y=72, so only its own 4px padding-top separates them. Rendered outside
    87	            the <ul> it instead picked up the column's 16px gap and sat 20px low against
    88	            Figma's 4px. */}
    89	        {group.fields.showContactChannels && (
    90	          <chakra.li __css={styles.listItem}>
    91	            <ZimmContactIconRow phoneHref={phoneHref} whatsAppHref={whatsAppHref} emailHref={emailHref} />
    92	          </chakra.li>
    93	        )}
    94	      </chakra.ul>
    95	    </chakra.div>
    96	  );
    97	};

