 1	const SubscribeSection = ({
 2	  heading,
 3	  body,
 4	  initialSubscribed = false,
 5	  privacyPolicyHref,
 6	  enableNameCapture = false,
 7	}: SubscribeSectionProps) => {
 8	  // Map the Storybook-only `initialSubscribed` flag to the success state.
 9	  // Post HPC-036, 'success' will only be reached via a confirmed Omneo response.
10	  const [submitState, setSubmitState] = useState<SubmitState>(initialSubscribed ? 'success' : 'idle');
11	  // Ref, not state: nothing renders from it, so a re-render on capture would be wasted.
12	  // The footer input unmounts once submitState leaves 'idle', so the email must be
13	  // captured here at step 1 or it is unrecoverable at step 2.
14	  const pendingSignupRef = useRef<PendingSignup>({ email: '', firstName: '', lastName: '' });
15	  const [modalOpen, setModalOpen] = useState(false);
16	  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});
17	
18	  const handleEmailSubmit = (email: string) => {
19	    pendingSignupRef.current.email = email;
20	    if (enableNameCapture) {
21	      setModalOpen(true);
22	      return;
23	    }
24	    // Descoped path, and the default. SFCC-55's AC scopes this section to "an email input field
25	    // and submit button as a placeholder component" and defers the Omneo sign-up to a separate
26	    // story. The name-capture modal is HPC-035/HPC-037 (both confirmed in .docs/prd/homepage.md
27	    // §6) but has no Figma node — all nine of its theme parts are undesigned, unlike the 27
28	    // Figma-referenced parts around it. So it does not ship enabled: submitting a valid email
29	    // goes straight to the placeholder message. Flip this prop on once Kiera supplies the design
30	    // and HPC-035 is scheduled; the modal and its coverage are already built and tested.
31	    setSubmitState('unavailable');
32	    pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
33	  };
34	
35	  const handleModalSubmit = (firstName: string, lastName: string) => {
36	    pendingSignupRef.current = { ...pendingSignupRef.current, firstName, lastName };
37	    // PLACEHOLDER until HPC-036 (Omneo integration) lands: POST pendingSignupRef.current here.
38	    // On confirmed response → setSubmitState('success'). On failure → setSubmitState('error').
39	    // 'unavailable' is shown until the integration is live; never show false success.
40	    setModalOpen(false);
41	    setSubmitState('unavailable');
42	    // Nothing was sent, so nothing needs retaining — the record holds customer PII and there
43	    // is no request for it to outlive. When HPC-036 adds the POST above, this reset stays; it
44	    // just moves to after a confirmed response. React memory only, never storage, never logged.
45	    pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
46	  };
47	
48	  return (
49	    <div>
50	      <chakra.p __css={styles.subscribeHeading}>{heading}</chakra.p>
51	      <chakra.p __css={styles.subscribeBody}>{body}</chakra.p>
52	      <chakra.div aria-live="polite" __css={styles.subscribeControl}>
53	        {submitState === 'idle' && (
54	          <ZimmInputAction
55	            label="Email"
56	            type="email"
57	            name="footer-email"
58	            icon="chevron-right"
59	            buttonLabel="Subscribe"
60	            inverse
61	            onSubmit={handleEmailSubmit}
62	          />
63	        )}
64	        {submitState === 'success' && <chakra.p __css={styles.subscribeSuccess}>{SUBSCRIBE_SUCCESS_MESSAGE}</chakra.p>}
65	        {(submitState === 'unavailable' || submitState === 'error') && (
66	          <chakra.p __css={styles.subscribeSuccess}>{SUBSCRIBE_UNAVAILABLE_MESSAGE}</chakra.p>
67	        )}
68	      </chakra.div>
69	
70	      {enableNameCapture && (
71	        <SubscribeModal
72	          isOpen={modalOpen}
73	          onClose={() => setModalOpen(false)}
74	          onSubmit={handleModalSubmit}
75	          privacyPolicyHref={privacyPolicyHref}
76	        />
77	      )}
78	    </div>
79	  );
80	};
81

