21	  closeModal: () => void;
22	  handleEmailSubmit: (email: string) => void;
23	  handleModalSubmit: (firstName: string, lastName: string) => void;
24	};
25	
26	/**
27	 * State machine for the subscribe section: the idle/unavailable/success/error submit states,
28	 * the optional HPC-035 name-capture modal, and the pending-signup payload assembled across both
29	 * steps.
30	 *
31	 * Extracted from ZimmSubscribeSection per components.md's extract-to-hook threshold (≥2 related
32	 * useState that change together — submitState and modalOpen here, plus the pendingSignupRef).
33	 *
34	 * @param params initialSubscribed (Storybook/test only) and enableNameCapture (HPC-035 opt-in)
35	 * @returns current submit/modal state plus the two submit handlers
36	 */
37	export const useSubscribeSection = ({
38	  initialSubscribed = false,
39	  enableNameCapture = false,
40	}: UseSubscribeSectionParams): UseSubscribeSectionReturn => {
41	  // Map the Storybook-only `initialSubscribed` flag to the success state.
42	  // Post HPC-036, 'success' will only be reached via a confirmed Omneo response.
43	  const [submitState, setSubmitState] = useState<SubmitState>(initialSubscribed ? 'success' : 'idle');
44	  // Ref, not state: nothing renders from it, so a re-render on capture would be wasted. The
45	  // footer input unmounts once submitState leaves 'idle', so the email must be captured here at
46	  // step 1 or it is unrecoverable at step 2.
47	  const pendingSignupRef = useRef<PendingSignup>({ email: '', firstName: '', lastName: '' });
48	  const [modalOpen, setModalOpen] = useState(false);
49	
50	  const handleEmailSubmit = (email: string) => {
51	    pendingSignupRef.current.email = email;
52	    if (enableNameCapture) {
53	      setModalOpen(true);
54	      return;
55	    }
56	    // Descoped path, and the default. SFCC-55's AC scopes this section to "an email input field
57	    // and submit button as a placeholder component" and defers the Omneo sign-up to a separate
58	    // story. The name-capture modal is HPC-035/HPC-037 but has no Figma node — all nine of its
59	    // theme parts are undesigned. So it does not ship enabled: submitting a valid email goes
60	    // straight to the placeholder message. Flip enableNameCapture on once Kiera supplies the
61	    // design and HPC-035 is scheduled; the modal and its coverage are already built and tested.
62	    setSubmitState('unavailable');
63	    pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
64	  };
65	
66	  const handleModalSubmit = (firstName: string, lastName: string) => {
67	    pendingSignupRef.current = { ...pendingSignupRef.current, firstName, lastName };
68	    // PLACEHOLDER until HPC-036 (Omneo integration) lands: POST pendingSignupRef.current here.
69	    // On confirmed response → setSubmitState('success'). On failure → setSubmitState('error').
70	    // 'unavailable' is shown until the integration is live; never show false success.
71	    setModalOpen(false);
72	    setSubmitState('unavailable');
73	    // Nothing was sent, so nothing needs retaining — the record holds customer PII and there is
74	    // no request for it to outlive. When HPC-036 adds the POST above, this reset stays; it just
75	    // moves to after a confirmed response. React memory only, never storage, never logged.
76	    pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
77	  };
78	
79	  return {
80	    submitState,
81	    modalOpen,
82	    // A Cancel (as opposed to a submit) is still an exit path for the captured email, so it
83	    // gets the same clear as handleModalSubmit — a shopper who backs out shouldn't leave PII
84	    // sitting in memory waiting for a signup that never completes.
85	    closeModal: () => {
86	      setModalOpen(false);
87	      pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
88	    },
89	    handleEmailSubmit,
90	    handleModalSubmit,
91	  };
92	};

